import { createSignal, createMemo, Show } from "solid-js";

export default function App() {
  const [count, setCount] = createSignal(0);
  const double = createMemo(() => count() * 2);

  return (
    <div class="min-h-screen flex items-center justify-center bg-gray-100">
      <div class="bg-white rounded-xl shadow-md p-8 text-center space-y-4">
        <h1 class="text-2xl font-bold">Contador</h1>

        <div class="flex items-center justify-center gap-6">
          <button
            class="w-10 h-10 rounded-full bg-blue-500 text-white text-xl hover:bg-blue-600"
            onClick={() => setCount(count() - 1)}
          >
            -
          </button>
          <span class="text-3xl font-bold min-w-[3ch]">{count()}</span>
          <button
            class="w-10 h-10 rounded-full bg-blue-500 text-white text-xl hover:bg-blue-600"
            onClick={() => setCount(count() + 1)}
          >
            +
          </button>
        </div>

        <p class="text-gray-700">El doble es {double()}</p>

        <Show when={count() > 5}>
          <p class="text-green-600 font-semibold">¡Más de 5!</p>
        </Show>
      </div>
    </div>
  );
}

