import { createSignal, createMemo, Show } from "solid-js";

export default function App() {
  const [email, setEmail] = createSignal("");
  const [password, setPassword] = createSignal("");
  const [submittedEmail, setSubmittedEmail] = createSignal<string | null>(null);

  const isValid = createMemo(
    () => email().includes("@") && password().length >= 8
  );

  const handleSubmit = (e: SubmitEvent) => {
    e.preventDefault();
    if (!isValid()) return;
    setSubmittedEmail(email());
  };

  return (
    <div class="min-h-screen flex items-center justify-center bg-gray-100 p-4">
      <div class="w-full max-w-sm bg-white rounded-lg shadow-md p-6">
        <Show
          when={submittedEmail() === null}
          fallback={
            <p class="text-center text-xl font-semibold text-gray-800">
              Bienvenido, {submittedEmail()}
            </p>
          }
        >
          <form onSubmit={handleSubmit} class="flex flex-col gap-4">
            <h1 class="text-2xl font-bold text-gray-800 text-center">
              Iniciar sesión
            </h1>

            <div class="flex flex-col gap-1">
              <label for="email" class="text-sm font-medium text-gray-700">
                Email
              </label>
              <input
                id="email"
                type="email"
                value={email()}
                onInput={(e) => setEmail(e.currentTarget.value)}
                placeholder="tu@email.com"
                class="border border-gray-300 rounded px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-500"
              />
            </div>

            <div class="flex flex-col gap-1">
              <label for="password" class="text-sm font-medium text-gray-700">
                Contraseña
              </label>
              <input
                id="password"
                type="password"
                value={password()}
                onInput={(e) => setPassword(e.currentTarget.value)}
                placeholder="Mínimo 8 caracteres"
                class="border border-gray-300 rounded px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-500"
              />
            </div>

            <button
              type="submit"
              disabled={!isValid()}
              class="bg-blue-600 text-white font-semibold rounded px-4 py-2 hover:bg-blue-700 disabled:bg-gray-300 disabled:text-gray-500 disabled:cursor-not-allowed"
            >
              Entrar
            </button>
          </form>
        </Show>
      </div>
    </div>
  );
}

