import { createSignal, createMemo, For, Show } from "solid-js";

interface User {
  id: number;
  name: string;
  email: string;
}

const initialUsers: User[] = [
  { id: 1, name: "Lucía Fernández", email: "lucia.fernandez@example.com" },
  { id: 2, name: "Martín Gómez", email: "martin.gomez@example.com" },
  { id: 3, name: "Sofía Rodríguez", email: "sofia.rodriguez@example.com" },
  { id: 4, name: "Mateo Álvarez", email: "mateo.alvarez@example.com" },
];

export default function App() {
  const [users] = createSignal<User[]>(initialUsers);
  const [query, setQuery] = createSignal("");

  const filtered = createMemo(() => {
    const q = query().trim().toLowerCase();
    if (!q) return users();
    return users().filter((u) => u.name.toLowerCase().includes(q));
  });

  return (
    <div class="min-h-screen bg-gray-100 p-6">
      <div class="mx-auto max-w-xl">
        <h1 class="mb-4 text-2xl font-bold text-gray-800">Usuarios</h1>

        <input
          type="text"
          placeholder="Buscar por nombre..."
          value={query()}
          onInput={(e) => setQuery(e.currentTarget.value)}
          class="w-full rounded-lg border border-gray-300 bg-white px-4 py-2 shadow-sm focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-200"
        />

        <p class="mt-3 text-sm text-gray-600">
          {filtered().length}{" "}
          {filtered().length === 1 ? "resultado" : "resultados"}
        </p>

        <div class="mt-4 space-y-3">
          <For each={filtered()}>
            {(user) => (
              <div class="rounded-lg bg-white p-4 shadow">
                <h2 class="text-lg font-semibold text-gray-900">{user.name}</h2>
                <p class="text-gray-600">{user.email}</p>
              </div>
            )}
          </For>

          <Show when={filtered().length === 0}>
            <p class="rounded-lg bg-white p-4 text-center text-gray-500 shadow">
              No se encontraron usuarios.
            </p>
          </Show>
        </div>
      </div>
    </div>
  );
}

