import { createSignal, createMemo, For, Show } from "solid-js";

type Product = {
  id: number;
  nombre: string;
  precio: number;
};

type CartItem = {
  id: number;
  cantidad: number;
};

const PRODUCTS: Product[] = [
  { id: 1, nombre: "Teclado mecánico", precio: 59.99 },
  { id: 2, nombre: "Mouse inalámbrico", precio: 24.5 },
  { id: 3, nombre: "Monitor 24\"", precio: 149.9 },
];

export default function App() {
  const [cart, setCart] = createSignal<CartItem[]>([]);

  const addToCart = (id: number) => {
    setCart((prev) => {
      const exists = prev.some((i) => i.id === id);
      if (exists) {
        return prev.map((i) =>
          i.id === id ? { ...i, cantidad: i.cantidad + 1 } : i
        );
      }
      return [...prev, { id, cantidad: 1 }];
    });
  };

  const changeQty = (id: number, delta: number) => {
    setCart((prev) =>
      prev
        .map((i) => (i.id === id ? { ...i, cantidad: i.cantidad + delta } : i))
        .filter((i) => i.cantidad > 0)
    );
  };

  const getProduct = (id: number) => PRODUCTS.find((p) => p.id === id)!;

  const total = createMemo(() =>
    cart().reduce((sum, i) => sum + getProduct(i.id).precio * i.cantidad, 0)
  );

  return (
    <div class="min-h-screen bg-gray-100 p-6">
      <div class="mx-auto grid max-w-4xl gap-6 md:grid-cols-2">
        <section class="rounded-lg bg-white p-4 shadow">
          <h2 class="mb-4 text-xl font-bold">Productos</h2>
          <ul class="space-y-3">
            <For each={PRODUCTS}>
              {(p) => (
                <li class="flex items-center justify-between rounded border p-3">
                  <div>
                    <p class="font-medium">{p.nombre}</p>
                    <p class="text-sm text-gray-600">${p.precio.toFixed(2)}</p>
                  </div>
                  <button
                    class="rounded bg-blue-600 px-3 py-1 text-white hover:bg-blue-700"
                    onClick={() => addToCart(p.id)}
                  >
                    Agregar
                  </button>
                </li>
              )}
            </For>
          </ul>
        </section>

        <section class="rounded-lg bg-white p-4 shadow">
          <h2 class="mb-4 text-xl font-bold">Carrito</h2>
          <Show
            when={cart().length > 0}
            fallback={<p class="text-gray-500">El carrito está vacío.</p>}
          >
            <ul class="space-y-3">
              <For each={cart()}>
                {(item) => {
                  const p = getProduct(item.id);
                  return (
                    <li class="flex items-center justify-between rounded border p-3">
                      <div>
                        <p class="font-medium">{p.nombre}</p>
                        <p class="text-sm text-gray-600">
                          ${p.precio.toFixed(2)} c/u
                        </p>
                      </div>
                      <div class="flex items-center gap-2">
                        <button
                          class="h-8 w-8 rounded bg-gray-200 hover:bg-gray-300"
                          onClick={() => changeQty(item.id, -1)}
                        >
                          -
                        </button>
                        <span class="w-6 text-center">{item.cantidad}</span>
                        <button
                          class="h-8 w-8 rounded bg-gray-200 hover:bg-gray-300"
                          onClick={() => changeQty(item.id, 1)}
                        >
                          +
                        </button>
                      </div>
                    </li>
                  );
                }}
              </For>
            </ul>
          </Show>
          <div class="mt-4 flex items-center justify-between border-t pt-4 text-lg font-bold">
            <span>Total:</span>
            <span>${total().toFixed(2)}</span>
          </div>
        </section>
      </div>
    </div>
  );
}

