import { createSignal, Show } from "solid-js";

const MIN = 0;
const MAX = 10;

export default function Counter() {
  const [count, setCount] = createSignal(0);
  const double = () => count() * 2;

  const decrement = () => setCount((c) => Math.max(MIN, c - 1));
  const increment = () => setCount((c) => Math.min(MAX, c + 1));
  const reset = () => setCount(0);

  return (
    <div class="flex flex-col gap-4 items-center">
      <h2>Contador</h2>
      <div class="flex items-center gap-2">
        <button
          class="disabled:opacity-50 disabled:cursor-not-allowed"
          disabled={count() <= MIN}
          onClick={decrement}
        >
          -
        </button>
        <span class="font-semibold">{count()}</span>
        <button
          class="primary disabled:opacity-50 disabled:cursor-not-allowed"
          disabled={count() >= MAX}
          onClick={increment}
        >
          +
        </button>
      </div>
      <button onClick={reset}>Reset</button>
      <span class="text-gray-500">El doble es {double()}</span>
      <Show when={count() > 5}>
        <span>¡Más de 5!</span>
      </Show>
      <Show when={count() >= MAX}>
        <span class="text-red-500">Llegaste al máximo (10)</span>
      </Show>
    </div>
  );
}

