import { createSignal, For, Show, onMount } from "solid-js";

interface User {
  id: string;
  name: string;
  email: string;
}

export default function App() {
  const [users, setUsers] = createSignal<User[]>([]);
  const [name, setName] = createSignal("");
  const [email, setEmail] = createSignal("");
  const [error, setError] = createSignal("");

  const load = async () => {
    try {
      const res = await fetch("/api/users");
      if (res.ok) setUsers(await res.json());
    } catch {
      /* ignore */
    }
  };

  onMount(load);

  const add = async () => {
    if (!email().includes("@")) {
      setError("Email inválido");
      return;
    }
    setError("");
    try {
      const res = await fetch("/api/users", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ name: name(), email: email() }),
      });
      if (res.ok) {
        const user: User = await res.json();
        setUsers((prev) => [...prev, user]);
        setName("");
        setEmail("");
      } else if (res.status === 400) {
        setError("Email inválido");
      }
    } catch {
      setError("Error de conexión");
    }
  };

  const remove = async (id: string) => {
    try {
      const res = await fetch(`/api/users/${encodeURIComponent(id)}`, {
        method: "DELETE",
      });
      if (res.ok || res.status === 404) {
        setUsers((prev) => prev.filter((u) => u.id !== id));
      }
    } catch {
      setError("Error de conexión");
    }
  };

  return (
    <div class="max-w-md mx-auto p-6">
      <h1 class="text-2xl font-bold mb-4">Usuarios</h1>
      <div class="flex flex-col gap-2 mb-4">
        <input
          class="border rounded px-3 py-2"
          placeholder="Nombre"
          value={name()}
          onInput={(e) => setName(e.currentTarget.value)}
        />
        <input
          class="border rounded px-3 py-2"
          placeholder="Email"
          value={email()}
          onInput={(e) => setEmail(e.currentTarget.value)}
        />
        <button
          class="bg-blue-600 text-white rounded px-3 py-2 hover:bg-blue-700"
          onClick={add}
        >
          Agregar
        </button>
        <Show when={error()}>
          <p class="text-red-600 text-sm">{error()}</p>
        </Show>
      </div>
      <ul class="flex flex-col gap-2">
        <For each={users()}>
          {(u) => (
            <li class="flex items-center justify-between border rounded px-3 py-2">
              <div>
                <div class="font-semibold">{u.name}</div>
                <div class="text-sm text-gray-600">{u.email}</div>
              </div>
              <button
                class="bg-red-500 text-white rounded px-2 py-1 hover:bg-red-600"
                onClick={() => remove(u.id)}
              >
                Borrar
              </button>
            </li>
          )}
        </For>
      </ul>
    </div>
  );
}

