    res.end();
    return;
  }
  res.writeHead(status, { "Content-Type": "application/json; charset=utf-8" });
  res.end(JSON.stringify(data));
}

function readBody(req: IncomingMessage): Promise<any> {
  return new Promise((resolve, reject) => {
    let data = "";
    req.on("data", (chunk) => {
      data += chunk;
      if (data.length > 1e6) {
        reject(new Error("too large"));
        req.destroy();
      }
    });
    req.on("end", () => {
      if (!data) return resolve({});
      try {
        resolve(JSON.parse(data));
      } catch (e) {
        reject(e);
      }
    });
    req.on("error", reject);
  });
}

const server = createServer(async (req, res) => {
  try {
    const url = new URL(req.url || "/", "http://localhost");
    const path = url.pathname.replace(/\/+$/, "") || "/";
    const method = req.method || "GET";

    if (path === "/api/items" && method === "GET") {
      return send(res, 200, items);
    }

    if (path === "/api/items" && method === "POST") {
      let body: any;
      try {
        body = await readBody(req);
      } catch {
        return send(res, 400, { error: "JSON inválido" });
      }
      const name = typeof body?.name === "string" ? body.name.trim() : "";
      if (!name) return send(res, 400, { error: "Nombre requerido" });
      const item: Item = { id: nextId++, name, bought: false };
      items.push(item);
      return send(res, 201, item);
    }

    const buyMatch = path.match(/^\/api\/items\/(\d+)\/buy$/);
    if (buyMatch && method === "POST") {
      const id = Number(buyMatch[1]);
      const item = items.find((i) => i.id === id);
      if (!item) return send(res, 404, { error: "No encontrado" });
      item.bought = true;
      return send(res, 200, item);
    }

    const delMatch = path.match(/^\/api\/items\/(\d+)$/);
    if (delMatch && method === "DELETE") {
      const id = Number(delMatch[1]);
      const exists = items.some((i) => i.id === id);
      if (!exists) return send(res, 404, { error: "No encontrado" });
      items = items.filter((i) => i.id !== id);
      return send(res, 204);
    }

    send(res, 404, { error: "No encontrado" });
  } catch {
    send(res, 500, { error: "Error interno" });
  }
});

server.listen(Number(process.env.PORT) || 3000);

