      <Header count={count()} />
      <Nav tab={tab()} onChange={setTab} />
      <Show when={tab() === "catalog"} fallback={<CartView cart={cart()} onChangeQty={changeQty} onClear={() => setCart([])} />}>
        <Catalog products={products()} onAdd={add} />
      </Show>
      <Footer />
    </div>
  );
}

