import { For, Show } from "solid-js";
import type { CartItem } from "./data";
import CartItemRow from "./CartItemRow";
import Summary from "./Summary";

type Props = { cart: CartItem[]; onChangeQty: (id: number, delta: number) => void; onClear: () => void };

export default function CartView(props: Props) {
  return (
    <Show when={props.cart.length > 0} fallback={<span class="text-gray-500">El carrito está vacío</span>}>
      <div class="flex flex-col gap-2">
        <For each={props.cart}>{(item) => <CartItemRow item={item} onChangeQty={(d) => props.onChangeQty(item.product.id, d)} />}</For>
        <Summary cart={props.cart} onClear={props.onClear} />
      </div>
    </Show>
  );
}

files.Catalog.tsx:
import { createSignal, For, Show } from "solid-js";
import type { Product } from "./data";
import SearchBox from "./SearchBox";
import ProductCard from "./ProductCard";

export default function Catalog(props: { products: Product[]; onAdd: (p: Product) => void }) {
  const [query, setQuery] = createSignal("");
  const [sorted, setSorted] = createSignal(false);
  const shown = () => {
    const filtered = props.products.filter((p) => p.name.toLowerCase().includes(query().toLowerCase()));
    return sorted() ? [...filtered].sort((a, b) => a.price - b.price) : filtered;
  };

  return (
    <div class="flex flex-col gap-2">
      <SearchBox value={query()} onChange={setQuery} />
      <button
        class="self-start rounded border px-3 py-1 hover:bg-gray-100"
        classList={{ "bg-gray-200 font-semibold": sorted() }}
        onClick={() => setSorted(!sorted())}
      >
        Ordenar por precio
      </button>
      <div class="grid grid-cols-3 gap-2">
        <For each={shown()}>{(p) => <ProductCard product={p} onAdd={() => props.onAdd(p)} />}</For>
      </div>
      <Show when={shown().length === 0}>
        <span class="text-gray-500">Sin resultados</span>
      </Show>
    </div>
  );
}

