  return (
    <div class="flex gap-2">
      <span class="font-semibold">{props.item.name}</span>
      <Show when={!props.item.active}>
        <span class="text-gray-500">(inactivo)</span>
      </Show>
      <span>Sueldo: {props.item.amount}</span>
      <button onClick={() => props.onToggle(props.item.id)}>Alternar</button>
    </div>
  );
}

